Method.Implementation:

	 try{
		 do ##super()
		$$$TRACE("Connect to " _ ..ApplicationAddress)		
		set ..objCdrTuxService = ##class(org.ihc.itf.cdr.microevents.MicroEventsFromCdr).%New(..JavaGateway,..ApplicationAddress, ..TuxedoService, ..LogDirectory _"/" _$$$JobConfigName _".log", $$$ConfigTrace($$$JobConfigName))		
     	set status = ..CheckObject()
	}catch err{
		$$$LOGERROR("Exception while getting Micro Info: " _err.AsSystemError() _ " _ data: " _ err.Data _ "; code:" _ err.Code)	    
	    Set status = ##class(IHC.ITF.ITFCOMMON.Utility).RetryMsgError(..%ConfigName," Exception while getting Micro Info from CDR: "_err.AsSystemError()_"::"_err.Data_"::"_err.Code)
	}

	quit status


 #dim status as %Status	 
 set status = $$$OK
 $$$TRACE("Inside OnMessage method......")

 	 $$$TRACE("objCdrTuxService Object valid: "_$IsObject(..objCdrTuxService))

 try{

	 if (..CheckObject() '= $$$OK) {
	 	$$$TRACE("**** Object does not exists ****")
	 	// Try to re intialize
	 	set result = ..OnInit()
		if (result '= $$$OK)
		{
			set status = ##class(IHC.ITF.ITFCOMMON.Utility).DisableMsgError("Op-Cdr-Results-Tux-DSQL", " Get Micro Events from CDR failed. MMI#: " _pRequest.mmiNumber_ ". Filler#: "_pRequest.fillerNumber_". SubType#: "_pRequest.subType_". EventTypeNcid#: "_pRequest.eventTypeNcid_". Event ID#: "_pRequest.eventId_" ; Reason: " _ result)						
			return status
		}
 	}

	$$$TRACE("Object name: " _ ..objCdrTuxService.%ClassName(1))

	 		$$$TRACE(" Calling Cdr Dsql Micro Event Info for the empi# .."_pRequest.mmiNumber_". Filler#: "_pRequest.fillerNumber_". SubType#: "_pRequest.subType_". EventTypeNcid#: "_pRequest.eventTypeNcid_". Event ID#: "_pRequest.eventId) 				 				 					 				 		
	 		set pResponse=##class(Ens.StringResponse).%New()
	 		if (pRequest.requestType ="getMicroEventsFromCDR") {	
	 		   Set pResponse.StringValue = ..objCdrTuxService.getMicroEventsFromCDR(pRequest.fillerNumber,pRequest.subType,pRequest.mmiNumber,pRequest.eventTypeNcid)
	 		   Set respData = pResponse.StringValue		 		
	 		   $$$TRACE(" Call after the getMicroEventsFromCDR response data: "_respData)		 				 		
	 		}elseif (pRequest.requestType ="getActionInfoFromCDR") {
		 	   Set pResponse.StringValue = ..objCdrTuxService.getActionInfoFromCDR(pRequest.eventId)
	 		   Set respData = pResponse.StringValue		 		
	 		   $$$TRACE(" Call after the getActionInfoFromCDR response data: "_respData)
	 		}elseif (pRequest.requestType ="getNcidByRelationshipNcid") {
		 	   Set pResponse.StringValue = ..objCdrTuxService.getNcidByRelationshipNcid(pRequest.ncid, pRequest.relationship)
		 	   Set respData = pResponse.StringValue
		 	   $$$TRACE("Call after the getNcidByRelationshipNcid response date: "_respData)
	 		}

 }catch err{	


       Set status = ..ExceptionHandler(err, "OnMessage")
 }

 $$$TRACE("OnMessage status: " _ status)	

 return status
